Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Invoke-RepositoryGit {
    param([Parameter(Mandatory)][string[]]$Arguments, [switch]$Capture)
    $output = & git --no-pager @Arguments 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw "git $($Arguments -join ' ') failed:`n$($output -join "`n")"
    }
    if ($Capture) { return ($output -join "`n").TrimEnd() }
    if ($output) { Write-Host ($output -join "`n") }
}

function Assert-CleanTree {
    if (Invoke-RepositoryGit -Arguments @('status', '--porcelain') -Capture) {
        throw 'Working tree must be clean, including untracked files. Commit or stash changes first.'
    }
}

function Get-PublishVersion {
    return [DateTime]::UtcNow.ToString('yyyy-MM-dd-HH-mm')
}

function Set-PublishVersion {
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][string]$Version)
    if ($Version -notmatch '^\d{4}-\d{2}-\d{2}-\d{2}-\d{2}$') {
        throw "Invalid publish timestamp: $Version"
    }
    $docs = Join-Path $Root 'docs'
    $pattern = '(?<attr>\b(?:src|href))="(?<path>(?!https?://)[^"?]+\.(?:css|js|webmanifest))(?:\?v=[^"]*)?"'
    foreach ($file in Get-ChildItem -LiteralPath $docs -Recurse -File -Filter index.html) {
        $content = Get-Content -LiteralPath $file.FullName -Raw
        $updated = [regex]::Replace($content, $pattern, {
            param($match)
            '{0}="{1}?v={2}"' -f $match.Groups['attr'].Value, $match.Groups['path'].Value, $Version
        })
        Set-Content -LiteralPath $file.FullName -Value $updated -Encoding utf8 -NoNewline
    }
    $workerPath = Join-Path $docs 'service-worker.js'
    $worker = Get-Content -LiteralPath $workerPath -Raw
    $cachePattern = "const CACHE_NAME = 'solitaire-v[^']+';"
    if ([regex]::Matches($worker, $cachePattern).Count -ne 1) {
        throw 'Expected exactly one Solitaire service worker cache declaration.'
    }
    $worker = [regex]::Replace($worker, $cachePattern, "const CACHE_NAME = 'solitaire-v$Version';")
    Set-Content -LiteralPath $workerPath -Value $worker -Encoding utf8 -NoNewline
}

function Get-PmItems {
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][string]$Folder)
    Get-ChildItem -LiteralPath (Join-Path $Root "PM\$Folder") -File -Filter '*.md' |
        Where-Object { $_.BaseName -match '^[a-z]+-\d{3,}$' } | Sort-Object Name
}

function Update-PmIndex {
    param([Parameter(Mandatory)][string]$Root)
    $path = Join-Path $Root 'PM\project-management.md'
    $existing = Get-Content -LiteralPath $path -Raw
    $header = [regex]::Match($existing, '\A<!--[\s\S]*?-->\s*')
    if (-not $header.Success) { throw 'PM index origin breadcrumb is missing.' }
    $lines = @($header.Value.TrimEnd(), '# Project management index')
    foreach ($folder in @('backlog', 'current', 'release-candidate-dev', 'release-candidate', 'completed')) {
        $lines += '', "## $folder/", ''
        $items = @(Get-PmItems -Root $Root -Folder $folder)
        if ($items.Count -eq 0) { $lines += '- (none)' }
        foreach ($item in $items) { $lines += "- [$($item.BaseName)]($folder/$($item.Name))" }
    }
    Set-Content -LiteralPath $path -Value ($lines -join "`n") -Encoding utf8
}

function Move-PmItem {
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][IO.FileInfo]$Item,
        [Parameter(Mandatory)][string]$Destination)
    $target = Join-Path $Root "PM\$Destination\$($Item.Name)"
    if (Test-Path -LiteralPath $target) { throw "PM destination already exists: $target" }
    Move-Item -LiteralPath $Item.FullName -Destination $target
}

